package co.edu.cinematch.core.service;
import co.edu.cinematch.core.exception.*; import co.edu.cinematch.core.model.*; import co.edu.cinematch.core.repository.*; import java.util.*;
public class PeliculaService { private final Repository<Pelicula> repo; public PeliculaService(Repository<Pelicula> r){repo=r;} public Pelicula crear(Pelicula p){validar(p);return repo.save(p);} public List<Pelicula> listar(){return repo.findAll();} public Pelicula buscar(String id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Película",id));} public Pelicula actualizar(String id,Pelicula datos){validar(datos);Pelicula p=buscar(id);p.setTitulo(datos.getTitulo());p.setSinopsis(datos.getSinopsis());p.setDuracion(datos.getDuracion());p.setGenero(datos.getGenero());p.setClasificacion(datos.getClasificacion());p.setIdioma(datos.getIdioma());p.setFechaEstreno(datos.getFechaEstreno());p.setRutaImagen(datos.getRutaImagen());return repo.save(p);} public void eliminar(String id){if(!repo.deleteById(id))throw new ResourceNotFoundException("Película",id);} private void validar(Pelicula p){if(p==null)throw new ValidationException("La película no puede ser nula.");if(blank(p.getTitulo()))throw new ValidationException("El título de la película es obligatorio.");if(p.getDuracion()<=0)throw new ValidationException("La duración debe ser mayor a 0 minutos.");if(blank(p.getGenero()))throw new ValidationException("El género es obligatorio.");} private boolean blank(String v){return v==null||v.trim().isEmpty();} }
